var s=[{title:`Válassz tesztet a célodhoz`,text:`Egy kontrollált fekvőtámasz-teszt a felsőtest erőállóképességét tükrözi, egy 30 másodperces felállás-teszt pedig az ismételt alsótesti működést méri. Egy időre végzett plank a törzsállóképesség egy bizonyos fajtáját teszteli, egy lépcsőteszt vagy mért séta pedig az állóképesség egy másik oldalát vizsgálja. Egyetlen teszt sem méri a teljes erőnlétet.`},{title:`Mindig ugyanúgy végezd`,text:`Használd ugyanazt a fekvőtámasz-mélységet, székmagasságot, plank-testhelyzetet vagy lépcsőmagasságot, és tartsd hasonlónak a bemelegítést, a pihenőt és a lábbelit. Állj meg, amikor a technikád összeomlik, ahelyett hogy magasabb számot hajszolnál. Több hét edzés után teszteld újra, ne végezz maximális erőfeszítést minden nap. Írd le pontosan, hogyan végezted az egyes teszteket, hogy a későbbi összehasonlításoknak legyen értelme.`},{title:`Válassz a szintedhez illő tesztet`,text:`Ha a nulláról indulsz, számolhatod a kényelmes székről való felállásokat egy stabil székkel. Egy tapasztalt edzőnek nehezebb mércére lehet szüksége. Ha egy teszt fájdalmat, szédülést, szokatlan légszomjat vagy egyensúlyvesztést okoz, ne használd, amíg szakember meg nem vizsgált.`},{title:`Ismerd a határokat`,text:`A gyakorlás, a motiváció, a fáradtság és a testarányok mind befolyásolják a terepi eredményeket. A jobb eredmény a jobb készségből is eredhet, nem csak fizikai változásból. A magad végezte tesztek nem diagnosztizálhatnak szív- és érrendszeri, neurológiai vagy mozgásszervi állapotokat.`}];var l=[{label:`CDC: idősebb felnőttek fizikai aktivitása`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/older-adults.html`},{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: séta az egészségért`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var a={sections:s,sources:l};export{a as default,s as sections,l as sources};